import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import { IconButton } from "@mui/material";
import shippingAPI from "../../services/shippingService";

export default function ManifestManagement() {
  const navigate = useNavigate();
  const [awbNumbers, setAwbNumbers] = useState("");
  const [loading, setLoading] = useState(false);
  const [manifestData, setManifestData] = useState(null);
  const [error, setError] = useState("");

  const handleGenerateManifest = async () => {
    const awbs = awbNumbers
      .split(/[\n,]/)
      .map(awb => awb.trim())
      .filter(awb => awb.length > 0);

    if (awbs.length === 0) {
      setError("Please enter at least one AWB number");
      return;
    }

    setLoading(true);
    setError("");
    setManifestData(null);

    try {
      const response = await shippingAPI.generateManifest(awbs.length === 1 ? awbs[0] : awbs);

      if (response?.data?.status) {
        setManifestData(response.data.data);
        setError("");
      } else {
        setError(response?.data?.message || "Failed to generate manifest");
      }
    } catch (error) {
      console.error("Error generating manifest:", error);
      setError(error.response?.data?.message || "Error generating manifest");
    } finally {
      setLoading(false);
    }
  };

  const handleDownloadManifest = () => {
    if (manifestData?.manifest_url) {
      window.open(manifestData.manifest_url, '_blank');
    }
  };

  const handlePrintManifest = () => {
    if (manifestData?.manifest_url) {
      const printWindow = window.open(manifestData.manifest_url, '_blank');
      printWindow.onload = () => {
        printWindow.print();
      };
    }
  };

  return (
    <div className="manifest-management">
      <div className="manifest-management__header">
        <IconButton
          aria-label="Back"
          className="back__button"
          onClick={() => navigate(-1)}
        >
          <ArrowBackIcon />
        </IconButton>
        <h3 className="page_heading">Generate Manifest</h3>
      </div>

      <div className="manifest-management__content">
        {/* Input Section */}
        <div className="manifest-input">
          <div className="input-section">
            <label htmlFor="awb-numbers">Enter AWB Numbers</label>
            <p className="input-help">
              Enter AWB numbers separated by commas or new lines
            </p>
            <textarea
              id="awb-numbers"
              value={awbNumbers}
              onChange={(e) => setAwbNumbers(e.target.value)}
              placeholder="Enter AWB numbers here...&#10;Example:&#10;XB123456789&#10;XB987654321&#10;XB555666777"
              rows={8}
              className="awb-textarea"
            />
          </div>

          <div className="action-section">
            <button
              onClick={handleGenerateManifest}
              disabled={loading}
              className="button-red generate-btn"
            >
              {loading ? "Generating..." : "Generate Manifest"}
            </button>
          </div>

          {error && <div className="error-message">{error}</div>}
        </div>

        {/* Results Section */}
        {manifestData && (
          <div className="manifest-results">
            <div className="results-header">
              <h4>Manifest Generated Successfully</h4>
              <div className="manifest-actions">
                {manifestData.manifest_url && (
                  <>
                    <button
                      onClick={handleDownloadManifest}
                      className="btn btn-secondary"
                    >
                      Download PDF
                    </button>
                    <button
                      onClick={handlePrintManifest}
                      className="btn btn-secondary"
                    >
                      Print Manifest
                    </button>
                  </>
                )}
              </div>
            </div>

            <div className="manifest-details">
              <div className="detail-grid">
                <div className="detail-item">
                  <label>Manifest ID:</label>
                  <span>{manifestData.manifest_id || 'N/A'}</span>
                </div>
                <div className="detail-item">
                  <label>Total Shipments:</label>
                  <span>{manifestData.total_shipments || 'N/A'}</span>
                </div>
                <div className="detail-item">
                  <label>Generated At:</label>
                  <span>{manifestData.generated_at ? new Date(manifestData.generated_at).toLocaleString() : 'N/A'}</span>
                </div>
                <div className="detail-item">
                  <label>Courier:</label>
                  <span>{manifestData.courier_name || 'Xpressbees'}</span>
                </div>
              </div>

              {manifestData.shipments && manifestData.shipments.length > 0 && (
                <div className="shipments-list">
                  <h5>Shipments in Manifest</h5>
                  <div className="shipments-table">
                    <table>
                      <thead>
                        <tr>
                          <th>AWB Number</th>
                          <th>Order ID</th>
                          <th>Status</th>
                          <th>Destination</th>
                        </tr>
                      </thead>
                      <tbody>
                        {manifestData.shipments.map((shipment, index) => (
                          <tr key={index}>
                            <td>{shipment.awb_number}</td>
                            <td>{shipment.order_number || 'N/A'}</td>
                            <td>
                              <span className="status-badge">
                                {shipment.status || 'Ready'}
                              </span>
                            </td>
                            <td>{shipment.destination || 'N/A'}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}
            </div>

            <div className="manifest-footer">
              <button
                className="btn btn-secondary"
                onClick={() => {
                  setManifestData(null);
                  setAwbNumbers("");
                  setError("");
                }}
              >
                Generate Another Manifest
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}